let sdkStageResults=[],sdkStageWaveforms=[];
const sdkPct=v=>Number.isFinite(Number(v))?(Number(v)*100).toFixed(2)+'%':'—';
const sdkSec=(v,settled=true)=>Number.isFinite(Number(v))?(settled?'':'>')+Math.round(Number(v))+' s':'—';
function drawSeries(ctx,values,x,y,color,width=2){if(!values?.length)return;ctx.beginPath();values.forEach((v,i)=>{const px=x(i),py=y(Number(v));i?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
function drawSdkWaveform(wave){const c=document.querySelector('#tunedScopeCanvas');if(!c||!wave)return;const dpr=devicePixelRatio||1,W=c.clientWidth,H=c.clientHeight,ctx=c.getContext('2d');c.width=W*dpr;c.height=H*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,W,H);const pad={l:44,r:44,t:20,b:28},pw=W-pad.l-pad.r,ph=H-pad.t-pad.b,n=Math.max(wave.SP.length,2);const process=[...wave.SP,...wave.PV_historical,...wave.PV_predicted].map(Number).filter(Number.isFinite),mv=[...wave.MV_historical,...wave.MV_predicted].map(Number).filter(Number.isFinite);let pmin=Math.min(...process),pmax=Math.max(...process),mmin=Math.min(...mv),mmax=Math.max(...mv);if(pmin===pmax){pmin-=1;pmax+=1}if(mmin===mmax){mmin-=1;mmax+=1}const x=i=>pad.l+i*pw/(n-1),yp=v=>pad.t+(pmax-v)*ph/(pmax-pmin),ym=v=>pad.t+(mmax-v)*ph/(mmax-mmin);ctx.strokeStyle='rgba(103,140,152,.17)';ctx.lineWidth=1;for(let i=0;i<6;i++){const yy=pad.t+i*ph/5;ctx.beginPath();ctx.moveTo(pad.l,yy);ctx.lineTo(W-pad.r,yy);ctx.stroke()}drawSeries(ctx,wave.SP,x,yp,'#f6ad3c',2);drawSeries(ctx,wave.PV_historical,x,yp,'#ff8066',1.6);drawSeries(ctx,wave.PV_predicted,x,yp,'#a7ef4f',2.4);drawSeries(ctx,wave.MV_historical,x,ym,'#55a4ff',1.3);drawSeries(ctx,wave.MV_predicted,x,ym,'#b98cff',2);ctx.font='11px Inter, sans-serif';ctx.fillStyle='#8fa6ae';ctx.textAlign='left';ctx.fillText(pmax.toFixed(2),4,pad.t+4);ctx.fillText(pmin.toFixed(2),4,H-pad.b);ctx.textAlign='right';ctx.fillText(mmax.toFixed(2),W-4,pad.t+4);ctx.fillText(mmin.toFixed(2),W-4,H-pad.b)}
function metricRow(label,cls,m){return `<span class="${cls}">${label}<b>${label.includes('V30')?'预测':'实测'}</b></span><span class="${cls}"><b>${sdkPct(m?.overshoot)}</b></span><span class="${cls}"><b>${sdkSec(m?.rise_time)}</b></span><span class="${cls}"><b>${sdkSec(m?.settling_time,m?.settled_within_window!==false)}</b></span><span class="${cls}"><b>${sdkPct(m?.steady_state_error)}</b></span>`}
function showSdkStage(stage){const s=sdkStageResults.find(x=>Number(x.stage)===Number(stage)),w=sdkStageWaveforms.find(x=>Number(x.stage)===Number(stage));if(!s||!w)return;document.querySelector('#stageScopePid').textContent=`Stage ${String(s.stage).padStart(2,'0')} · V30 Kc ${Number(s.Kc).toFixed(6)} · tauI ${Number(s.tauI).toFixed(3)} s · tauD ${Number(s.tauD||0).toFixed(3)} s`;document.querySelector('#stageScopeState').textContent=`● V30 SDK · STAGE ${String(s.stage).padStart(2,'0')} / ${sdkStageResults.length}`;document.querySelector('#stageScopeMetrics').innerHTML=`<span class="head">性能指标<b>同一 SDK metrics()</b></span><span class="head">超调<b>Overshoot</b></span><span class="head">上升时间<b>Rise time</b></span><span class="head">调节时间<b>Settling</b></span><span class="head">稳态误差<b>Steady error</b></span>${metricRow('历史数据','manual',w.historical_metrics)}${metricRow('V30 自整定','auto',w.metrics)}`;document.querySelectorAll('#stageRows tr').forEach(tr=>tr.classList.toggle('scope-active',Number(tr.dataset.stageRow)===Number(stage)));drawSdkWaveform(w)}
function applySdkResult(result,waveformPayload){sdkStageResults=Array.isArray(result.stage_results)?result.stage_results:[];sdkStageWaveforms=Array.isArray(waveformPayload?.waveforms)?waveformPayload.waveforms:[];const ready=sdkStageResults.length&&sdkStageWaveforms.length;document.querySelector('#sdkStageCard').hidden=!sdkStageResults.length;document.querySelector('#sdkScopeCard').hidden=!ready;const target=document.querySelector('#stageRows'),select=document.querySelector('#stageScopeSelect');target.innerHTML=sdkStageResults.map(s=>`<tr data-stage-row="${s.stage}"><td>Stage ${String(s.stage).padStart(2,'0')}</td><td>${Number(s.Kc).toFixed(6)}</td><td>${Number(s.tauI).toFixed(3)}</td><td>${Number(s.tauD||0).toFixed(3)}</td><td>${sdkPct(s.overshoot)}</td><td>${sdkSec(s.rise_time)}</td><td>${sdkSec(s.settling_time,s.settled_within_window!==false)}</td><td>${sdkPct(s.steady_state_error)}</td><td><span class="decision ${s.accepted===false?'hold':'accepted'}">${s.accepted===false?'保持上一组':'SDK 建议'}</span></td><td><button class="stage-use" data-stage="${s.stage}">查看并采用</button></td></tr>`).join('');select.innerHTML=sdkStageWaveforms.map(w=>`<option value="${w.stage}">Stage ${String(w.stage).padStart(2,'0')}</option>`).join('');select.onchange=()=>showSdkStage(select.value);document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{const s=sdkStageResults.find(x=>Number(x.stage)===Number(b.dataset.stage));select.value=String(s.stage);showSdkStage(s.stage);document.querySelector('#kp').value=s.Kc;document.querySelector('#ti').value=s.tauI;document.querySelector('#td').value=s.tauD||0;toast(`已载入 SDK Stage ${s.stage} 建议，未写入 DCS`)});if(ready)showSdkStage(sdkStageWaveforms[0].stage)}
function clearSdkResults(reason='等待运行 V30 SDK'){sdkStageResults=[];sdkStageWaveforms=[];document.querySelector('#sdkScopeCard').hidden=true;document.querySelector('#sdkStageCard').hidden=true;document.querySelector('#stageRows').innerHTML='';document.querySelector('#stageScopeMetrics').innerHTML='';document.querySelector('#stageScopePid').textContent=reason}
const applySdkResultBase=applySdkResult;
applySdkResult=(result,payload)=>applySdkResultBase(result,{...payload,waveforms:(payload?.waveforms||[]).map(w=>w.manual?{...w,PV_historical:w.manual.PV_predicted,MV_historical:w.manual.MV_predicted,historical_metrics:w.manual.metrics}:w)});
clearSdkResults();
